const incoming = $json.body || $json;
let raw = incoming.raw_payload || {};
if (typeof raw === 'string') { try { raw = JSON.parse(raw); } catch { raw = {}; } }

const severity = String(incoming.severity || 'medium').toLowerCase();
const eventType = String(incoming.event_type || 'unknown').toLowerCase();
const sourceIp = incoming.src_ip || incoming.source_ip || raw.src_ip || raw.srcip || '';
const processId = String(incoming.process_id || raw.process_id || raw.pid || raw.process?.pid || '');
const url = incoming.url || raw.url || '';
const domain = incoming.domain || raw.domain || '';

return { json: {
  alert_id: incoming.alert_id || `n8n-${Date.now()}`,
  agent_id: incoming.agent_id || incoming.agent?.id || '',
  event_type: eventType,
  severity,
  title: incoming.title || 'SOC Security Alert',
  description: incoming.description || incoming.message || '',
  src_ip: sourceIp,
  process_id: processId,
  url,
  domain,
  timestamp: incoming.timestamp || new Date().toISOString(),
  raw_payload: raw
} };

const alert = $('Normalize SOC Alert').item.json;
let ai = {};
try { ai = typeof $json.response === 'string' ? JSON.parse($json.response) : ($json.response || $json); } catch { ai = {}; }

const allowed = ['block_ip', 'kill_process', 'block_url', 'create_case', 'ignore'];
let action = allowed.includes(ai.action) ? ai.action : 'create_case';
const confidence = Math.max(0, Math.min(1, Number(ai.confidence) || 0));

if (action === 'block_ip' && !alert.src_ip) action = 'create_case';
if (action === 'kill_process' && (!alert.process_id || !alert.agent_id)) action = 'create_case';
if (action === 'block_url' && !alert.domain && !alert.url) action = 'create_case';

return { json: {
  ...alert,
  action,
  ai_used: true,
  ai_verdict: ai.verdict || 'unknown',
  ai_confidence: confidence,
  reason: ai.reason || 'AI khong cung cap ly do hop le.',
  requires_approval: ['block_ip', 'kill_process', 'block_url'].includes(action)
} };

